import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    min_heap = []

    for i in range(N):
        for j in range(N):
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < N and 0 <= nj < N:
                    heapq.heappush(min_heap, (grid[i][j] + grid[ni][nj], [(i, j), (ni, nj)]))

    while min_heap:
        total, path = heapq.heappop(min_heap)
        if len(path) == k:
            result = [grid[x][y] for x, y in path]
            return result

        for di, dj in directions:
            ni, nj = path[-1][0] + di, path[-1][1] + dj
            if (ni, nj) not in path:
                new_path = path + [(ni, nj)]
                heapq.heappush(min_heap, (total + grid[ni][nj], new_path))
