import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    min_heap = []

    for i in range(N):
        for j in range(N):
            heapq.heappush(min_heap, (grid[i][j], i, j, [(i, j)]))

    while min_heap:
        val, x, y, path = heapq.heappop(min_heap)

        if len(path) == k:
            return [grid[i][j] for i, j in path]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in path:
                new_path = path + [(nx, ny)]
                heapq.heappush(min_heap, (val + grid[nx][ny], nx, ny, new_path))

    return []
```

