def f(n):
    def factorial(x):
        if x == 0 or x == 1:
            return 1
        result = 1
        for i in range(1, x + 1):
            result *= i
        return result

    def sum_up_to(x):
        return sum(range(1, x + 1))

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_up_to(i))
    return result
