def match_parens(lst):
    s1, s2 = lst
    # Check if the sum of parentheses in both strings is balanced
    if (s1.count('(') + s2.count('(')) != (s1.count(')') + s2.count(')')):
        return 'No'
    # Check if at any point the number of closing parentheses exceeds the number of opening ones
    balance = 0
