def prime_fib(n: int):
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    def fib(num):
        a, b = 0, 1
        while a < num:
            a, b = b, a + b
        return a == num

    primes_fib = []
    i = 2
    while len(primes_fib) < n:
        if is_prime(i) and fib(i):
            primes_fib.append(i)
        i += 1
    return primes_fib[-1]
