import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    min_heap = []

    for i in range(N):
        for j in range(N):
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < N and 0 <= nj < N:
                    heapq.heappush(min_heap, (grid[i][j], i, j, [(i, j)]))

    while min_heap:
        value, x, y, path = heapq.heappop(min_heap)
        if len(path) == k:
            return [grid[i][j] for i, j in path]
        for di, dj in directions:
            ni, nj = x + di, y + dj
            if 0 <= ni < N and 0 <= nj < N and (ni, nj) not in path:
                new_path = path + [(ni, nj)]
                heapq.heappush(min_heap, (grid[ni][nj], ni, nj, new_path))

    return []
```

