import math

def poly(xs: list, x: float):
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    if len(xs) % 2 == 0 or xs[-1] == 0:
        raise ValueError("Invalid input: list must have an odd number of coefficients and a non-zero leading coefficient.")

    def f(x):
        return poly(xs, x)

    def f_prime(x):
        return poly([coeff * i for i, coeff in enumerate(xs)], x)

    x0 = 1.0
    x1 = 2.0
    while abs(f(x1)) > 1e-7:
        x0, x1 = x1, x1 - f(x1) / f_prime(x1)
    return x1
